const scoreboardRaw = $('Fetch NBA Scoreboard').first().json;
const oddsRaw = $('Fetch Live Odds').all().map(i => i.json);
const history = $('Fetch Historical Data').all().map(i => i.json);

// Check for fetch errors
const errors = [];
if (scoreboardRaw.error) errors.push('Scoreboard fetch failed: ' + scoreboardRaw.error);
if (!oddsRaw.length || oddsRaw[0].error) errors.push('Odds fetch failed');

const games = Array.isArray(oddsRaw) ? oddsRaw.filter(g => !g.error) : [];
if (!games.length) {
  return [{ json: { error: 'No games available', details: errors } }];
}

const analyses = games.map(game => {
  const homeTeam = game.home_team;
  const awayTeam = game.away_team;
  const bookmakers = game.bookmakers || [];

  // Line shopping: find best odds for BOTH sides across all markets
  const best = { spread: {}, total: {}, moneyline: {} };

  for (const book of bookmakers) {
    for (const market of (book.markets || [])) {
      const outcomes = market.outcomes || [];
      if (market.key === 'spreads') {
        for (const o of outcomes) {
          const side = o.name === homeTeam ? 'home' : 'away';
          if (!best.spread[side] || o.price > best.spread[side].price) {
            best.spread[side] = { name: o.name, point: o.point, price: o.price, book: book.title };
          }
        }
      }
      if (market.key === 'totals') {
        for (const o of outcomes) {
          const side = o.name === 'Over' ? 'over' : 'under';
          if (!best.total[side] || o.price > best.total[side].price) {
            best.total[side] = { point: o.point, price: o.price, book: book.title };
          }
        }
      }
      if (market.key === 'h2h') {
        for (const o of outcomes) {
          const side = o.name === homeTeam ? 'home' : 'away';
          if (!best.moneyline[side] || o.price > best.moneyline[side].price) {
            best.moneyline[side] = { name: o.name, price: o.price, book: book.title };
          }
        }
      }
    }
  }

  // Consensus lines (average across all books)
  let spreadSum = 0, spreadN = 0, totalSum = 0, totalN = 0;
  for (const book of bookmakers) {
    for (const market of (book.markets || [])) {
      if (market.key === 'spreads') {
        const ho = (market.outcomes || []).find(o => o.name === homeTeam);
        if (ho) { spreadSum += ho.point; spreadN++; }
      }
      if (market.key === 'totals') {
        const ov = (market.outcomes || []).find(o => o.name === 'Over');
        if (ov) { totalSum += ov.point; totalN++; }
      }
    }
  }

  // Historical accuracy for these teams
  const relevant = history.filter(h =>
    [h.home_team, h.away_team].includes(homeTeam) ||
    [h.home_team, h.away_team].includes(awayTeam)
  );
  const closed = relevant.filter(h => h.outcome);
  const wins = closed.filter(h => h.outcome === 'win').length;

  return {
    game_id: game.id,
    home_team: homeTeam,
    away_team: awayTeam,
    commence_time: game.commence_time,
    consensus_spread: spreadN ? +(spreadSum / spreadN).toFixed(1) : null,
    consensus_total: totalN ? +(totalSum / totalN).toFixed(1) : null,
    best_lines: best,
    bookmaker_count: bookmakers.length,
    history: {
      sample_size: closed.length,
      win_rate: closed.length ? +(wins / closed.length * 100).toFixed(1) : null
    },
    fetch_errors: errors.length ? errors : undefined
  };
});

return analyses.map(a => ({ json: a }));

const matchup = $('Analyze Matchups').item.json;
const aiOutput = $('AI Edge Analysis').item.json;
const storeResult = $('Store Analysis').item.json;

return [{
  json: {
    game_id: matchup.game_id,
    home_team: matchup.home_team,
    away_team: matchup.away_team,
    commence_time: matchup.commence_time,
    consensus_spread: matchup.consensus_spread,
    consensus_total: matchup.consensus_total,
    best_lines: matchup.best_lines,
    bookmaker_count: matchup.bookmaker_count,
    history: matchup.history,
    ai_analysis: aiOutput.output || aiOutput.text || aiOutput,
    analysis_run_id: storeResult.id || null,
    stored: !storeResult.error
  }
}];
